settings.custom_liquid:
{% assign variant = closest.product.selected_or_first_available_variant %}

<div class="product-inventory">
  {% if closest.product == blank %}
    <span style="color:red;">DEBUG: closest.product also blank</span>
  {% elsif variant.inventory_management != 'shopify' %}
    <span style="color:red;">DEBUG: inventory_management = "{{ variant.inventory_management }}"</span>
  {% else %}
    {% if variant.inventory_quantity > 0 and variant.inventory_quantity <= 10 %}
      <span class="product-inventory__badge product-inventory__badge--low">{{ variant.inventory_quantity }} left</span>
    {% elsif variant.inventory_quantity > 10 %}
      <span class="product-inventory__badge product-inventory__badge--ok">{{ variant.inventory_quantity }} left</span>
    {% else %}
      {% if variant.inventory_policy == 'continue' %}
        <span class="product-inventory__badge product-inventory__badge--backorder">Backorder</span>
      {% else %}
        <span class="product-inventory__badge product-inventory__badge--out">Out of stock</span>
      {% endif %}
    {% endif %}
  {% endif %}
</div>

<style>
  .product-inventory__badge { display:inline-block; font-size:10px; font-weight:700; padding:0.3rem 0.7rem; border-radius:4px; }
  .product-inventory__badge--low { background:#FCE6D6; color:#C25A1E; }
  .product-inventory__badge--ok { background:#E3F3E9; color:#2E7D4F; }
  .product-inventory__badge--out { background:#FBE4E4; color:#B0231C; }
  .product-inventory__badge--backorder { background:#EAF2FB; color:#2F6FED; }
</style>

